"use client";
import { FormEvent, useEffect, useRef, useState } from "react";

type User={id:number;name:string;phone:string;email:string;role:string;avatar_url?:string};
type RoleOption={code:string;name:string;builtin:boolean};
type Candidate={id:number;name:string;phone?:string;email?:string;city?:string;current_company?:string;current_title?:string;school?:string;degree?:string;gender?:string;graduation_time?:string;years?:number;expected_salary?:string;summary?:string;visibility?:string;owner_id:number;owner_name?:string;can_view_contact:boolean;notes?:Note[];attachments?:Attachment[];applications?:Application[]};
type Client={id:number;name:string;industry?:string;contact_name?:string;contact_phone?:string;owner_id:number};
type Job={id:number;title:string;client_id:number;city?:string;salary?:string;status:string;owner_id:number};
type Application={id:number;candidate_id:number;job_id:number;stage:string;updated_at:string};
type Note={id:number;content:string;author_id:number;created_at:string};
type Attachment={id:number;name:string;size:number;created_at:string};
type Dashboard={candidates:number;clients:number;open_jobs:number;active_pipeline:number;stages:Record<string,number>};
type Sender={id:number;client_id?:number;display_name:string;form_header:string;interview_requirements?:string;sms_signature?:string;enabled:boolean};
type ResumeFlow={id:number;token:string;candidate_id:number;candidate_name:string;job_id?:number;job_title?:string;sender_id?:number;sender_name:string;form_header:string;interview_requirements?:string;flow_type:string;recipient_phone:string;title:string;message?:string;status:string;sms_status:string;answers?:Record<string,string>;created_at:string;submitted_at?:string;public_url:string};
type FormTemplate={id:number;name:string;template_type:string;sender_id?:number;description?:string;fields:{label:string;type:string;required?:boolean;options?:string[]}[];source_file_name?:string};
type View="dashboard"|"candidates"|"clients"|"jobs"|"pipeline"|"resumeFlow"|"settings"|"profile";
const stages=["搜寻","联系","推荐","面试","Offer","入职","保证期","回款"];
const apiBase=()=>typeof window==="undefined"?"/api":`http://${window.location.hostname}:8000/api`;

export default function Home(){
 const[token,setToken]=useState("");const[user,setUser]=useState<User|null>(null);const[view,setView]=useState<View>("dashboard");const[people,setPeople]=useState<Candidate[]>([]);const[clients,setClients]=useState<Client[]>([]);const[jobs,setJobs]=useState<Job[]>([]);const[apps,setApps]=useState<Application[]>([]);const[users,setUsers]=useState<User[]>([]);const[roles,setRoles]=useState<RoleOption[]>([]);const[flows,setFlows]=useState<ResumeFlow[]>([]);const[senders,setSenders]=useState<Sender[]>([]);const[templates,setTemplates]=useState<FormTemplate[]>([]);const[publicToken,setPublicToken]=useState<string|null>(null);const[dash,setDash]=useState<Dashboard|null>(null);const[selected,setSelected]=useState<Candidate|null>(null);const[modal,setModal]=useState<"candidate"|"candidateEdit"|"client"|"job"|"user"|"application"|"resumeUpload"|"resumeFlow"|"sender"|"template"|null>(null);const[editing,setEditing]=useState<Candidate|Client|Job|null>(null);const[templateEditing,setTemplateEditing]=useState<FormTemplate|null>(null);const[query,setQuery]=useState("");const[error,setError]=useState("");const fileRef=useRef<HTMLInputElement>(null);
 const headers=(json=false)=>({Authorization:`Bearer ${token}`,...(json?{"Content-Type":"application/json"}:{})});
 async function req(path:string,options:RequestInit={}){const r=await fetch(`${apiBase()}${path}`,options);if(r.status===401){logout();throw new Error("登录已过期")};if(!r.ok){let x:any={};try{x=await r.json()}catch{};throw new Error(typeof x.detail==="string"?x.detail:x.detail?.message||"操作失败")};return r.status===204?null:r.json()}
 async function refresh(t=token){const auth={Authorization:`Bearer ${t}`};const [p,c,j,a,d]=await Promise.all([reqWith("/candidates",auth),reqWith("/clients",auth),reqWith("/jobs",auth),reqWith("/pipeline",auth),reqWith("/dashboard",auth)]);setPeople(p);setClients(c);setJobs(j);setApps(a);setDash(d);if((user?.role==="admin"||user?.role==="manager")){try{const [members,roleList]=await Promise.all([reqWith("/users",auth),reqWith("/roles",auth)]);setUsers(members);setRoles(roleList)}catch{}}}
 async function refreshFlows(t=token){const auth={Authorization:`Bearer ${t}`};const [f,s,m]=await Promise.all([reqWith("/resume-flow",auth),reqWith("/resume-flow/senders",auth),reqWith("/resume-flow/templates",auth)]);setFlows(f);setSenders(s);setTemplates(m)}
 async function reqWith(path:string,h:Record<string,string>){const r=await fetch(`${apiBase()}${path}`,{headers:h});if(!r.ok)throw new Error();return r.json()}
 useEffect(()=>{const t=sessionStorage.getItem("lingyao_token"),u=sessionStorage.getItem("lingyao_user");if(t&&u){try{const parsed=JSON.parse(u);if(!parsed?.name||!parsed?.role)throw new Error("invalid cached user");setToken(t);setUser(parsed);const auth={Authorization:`Bearer ${t}`};Promise.all([reqWith("/candidates",auth),reqWith("/clients",auth),reqWith("/jobs",auth),reqWith("/pipeline",auth),reqWith("/dashboard",auth),reqWith("/me",auth)]).then(([p,c,j,a,d,me])=>{if(!me?.name||!me?.role)throw new Error("invalid user");setPeople(p);setClients(c);setJobs(j);setApps(a);setDash(d);setUser(me);sessionStorage.setItem("lingyao_user",JSON.stringify(me))}).catch(()=>logout())}catch{logout()}}},[]);
 useEffect(()=>{setPublicToken(new URLSearchParams(window.location.search).get("form"))},[]);
 async function login(e:FormEvent<HTMLFormElement>){e.preventDefault();setError("");const f=new FormData(e.currentTarget);try{const r=await fetch(`${apiBase()}/auth/login`,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({phone:f.get("phone"),password:f.get("password")})});if(!r.ok)throw new Error();const x=await r.json();setToken(x.access_token);const auth={Authorization:`Bearer ${x.access_token}`};const [p,c,j,a,d,me]=await Promise.all([reqWith("/candidates",auth),reqWith("/clients",auth),reqWith("/jobs",auth),reqWith("/pipeline",auth),reqWith("/dashboard",auth),reqWith("/me",auth)]);sessionStorage.setItem("lingyao_token",x.access_token);sessionStorage.setItem("lingyao_user",JSON.stringify(me));setUser(me);setPeople(p);setClients(c);setJobs(j);setApps(a);setDash(d)}catch{setError("手机号或密码错误，密码应为6位数字。")}}
 function logout(){sessionStorage.clear();setToken("");setUser(null);setSelected(null)}
 async function chooseView(v:View){setView(v);setSelected(null);if((v==="settings"||v==="candidates")&&(user?.role==="admin"||user?.role==="manager")){try{const [members,roleList]=await Promise.all([req("/users",{headers:headers()}),req("/roles",{headers:headers()})]);setUsers(members);setRoles(roleList)}catch{}}}
 useEffect(()=>{if(token&&view==="resumeFlow")refreshFlows().catch(()=>{})},[view,token]);
 async function openCandidate(c:Candidate){setSelected(await req(`/candidates/${c.id}`,{headers:headers()}))}
 async function submitEntity(e:FormEvent<HTMLFormElement>){e.preventDefault();const f=new FormData(e.currentTarget),raw=Object.fromEntries(f);try{if(modal==="candidate")await req("/candidates",{method:"POST",headers:headers(true),body:JSON.stringify({...raw,years:raw.years?Number(raw.years):null,owner_id:raw.owner_id?Number(raw.owner_id):null})});if(modal==="candidateEdit"&&editing)await req(`/candidates/${editing.id}`,{method:"PUT",headers:headers(true),body:JSON.stringify({...raw,years:raw.years?Number(raw.years):null,owner_id:Number(raw.owner_id)})});if(modal==="client")await req(editing?`/clients/${editing.id}`:"/clients",{method:editing?"PUT":"POST",headers:headers(true),body:JSON.stringify(raw)});if(modal==="job")await req(editing?`/jobs/${editing.id}`:"/jobs",{method:editing?"PUT":"POST",headers:headers(true),body:JSON.stringify({...raw,client_id:Number(raw.client_id)})});if(modal==="user")await req("/users",{method:"POST",headers:headers(true),body:JSON.stringify(raw)});if(modal==="application")await req("/pipeline",{method:"POST",headers:headers(true),body:JSON.stringify({...raw,candidate_id:Number(raw.candidate_id),job_id:Number(raw.job_id)})});setModal(null);setEditing(null);await refresh()}catch(e){alert((e as Error).message)}}
 async function submitFlow(e:FormEvent<HTMLFormElement>){e.preventDefault();const form=new FormData(e.currentTarget),raw=Object.fromEntries(form);try{if(modal==="sender"){await req("/resume-flow/senders",{method:"POST",headers:headers(true),body:JSON.stringify({...raw,client_id:raw.client_id?Number(raw.client_id):null,enabled:true})})}else if(modal==="template"){const file=form.get("file") as File;if(file?.size){await req("/resume-flow/templates/upload",{method:"POST",headers:headers(),body:form})}else{const fields=String(raw.questions||"").split("\n").map(line=>{const [label,type="text",opts=""]=line.split("|").map(x=>x.trim());return {label,type,required:true,options:opts?opts.split(",").map(x=>x.trim()):undefined}}).filter(x=>x.label);await req("/resume-flow/templates",{method:"POST",headers:headers(true),body:JSON.stringify({name:raw.name,template_type:raw.template_type,sender_id:raw.sender_id?Number(raw.sender_id):null,description:raw.description,fields})})}}else{const chosen=templates.find(t=>t.template_type===raw.flow_type);const x=await req("/resume-flow",{method:"POST",headers:headers(true),body:JSON.stringify({...raw,candidate_id:Number(raw.candidate_id),job_id:raw.job_id?Number(raw.job_id):null,sender_id:raw.sender_id?Number(raw.sender_id):null,template_id:chosen?.id||null})});if(navigator.clipboard)await navigator.clipboard.writeText(x.public_url);alert(`${x.sms_status}\n候选人链接已复制：\n${x.public_url}`)}setModal(null);await refreshFlows()}catch(e){alert((e as Error).message)}}
 async function updateTemplate(e:FormEvent<HTMLFormElement>){e.preventDefault();if(!templateEditing)return;const raw=Object.fromEntries(new FormData(e.currentTarget));const fields=String(raw.questions||"").split("\\n").map(line=>{const [label,type="text",opts=""]=line.split("|").map(x=>x.trim());return {label,type,required:true,options:opts?opts.split(",").map(x=>x.trim()):undefined}}).filter(x=>x.label);try{await req("/resume-flow/templates/"+templateEditing.id,{method:"PUT",headers:headers(true),body:JSON.stringify({name:raw.name,template_type:raw.template_type,sender_id:raw.sender_id?Number(raw.sender_id):null,description:raw.description,fields})});setTemplateEditing(null);await refreshFlows()}catch(e){alert((e as Error).message)}}
 async function deleteTemplate(t:FormTemplate){if(!confirm("确认删除模板“"+t.name+"”？已回收的填写记录不会删除。"))return;try{await req("/resume-flow/templates/"+t.id,{method:"DELETE",headers:headers()});await refreshFlows()}catch(e){alert((e as Error).message)}}
 function printFlow(x:ResumeFlow){const rows=Object.entries(x.answers||{}).map(([k,v])=>`<tr><th>${k}</th><td>${String(v)}</td></tr>`).join("");const w=window.open("","_blank");w?.document.write(`<html><head><title>${x.title}</title><style>body{font-family:Arial;padding:40px;color:#222}h1{text-align:center}table{width:100%;border-collapse:collapse;margin-top:24px}th,td{border:1px solid #bbb;padding:10px;text-align:left}th{width:180px;background:#f5f5f5}</style></head><body><h1>${x.form_header}</h1><h3>${x.sender_name}</h3><p>候选人：${x.candidate_name}</p><p>职位：${x.job_title||"—"}</p><table>${rows||"<tr><td>尚未填写</td></tr>"}</table><script>window.print()</script></body></html>`);w?.document.close()}
 async function copyLink(x:ResumeFlow){await navigator.clipboard.writeText(x.public_url);alert("链接已复制，可通过短信发送给候选人。")}
 async function addNote(e:FormEvent<HTMLFormElement>){e.preventDefault();if(!selected)return;const f=new FormData(e.currentTarget);await req(`/candidates/${selected.id}/notes`,{method:"POST",headers:headers(true),body:JSON.stringify({content:f.get("content")})});(e.currentTarget as HTMLFormElement).reset();await openCandidate(selected)}
 async function uploadAttachment(file?:File){if(!file||!selected)return;const f=new FormData();f.append("file",file);await req(`/candidates/${selected.id}/attachments`,{method:"POST",headers:headers(),body:f});await openCandidate(selected)}
 async function uploadResume(e:FormEvent<HTMLFormElement>){e.preventDefault();const f=new FormData(e.currentTarget);const file=f.get("file") as File;if(!file?.size){alert("请选择简历文件");return}try{const x=await req("/resumes/import",{method:"POST",headers:headers(),body:f});setModal(null);await refresh();alert(x.created?`简历已上传，并自动创建人才档案：${x.candidate.name}`:`检测到重复人才，简历已保存到现有档案：${x.candidate.name}`)}catch(e){alert((e as Error).message)}}
 async function downloadAttachment(a:Attachment){const r=await fetch(`${apiBase()}/attachments/${a.id}`,{headers:headers()});if(!r.ok){alert("附件下载失败");return}const url=URL.createObjectURL(await r.blob());const link=document.createElement("a");link.href=url;link.download=a.name;link.click();URL.revokeObjectURL(url)}
 async function updateMember(member:User,action:"password"|"disable"|"enable"|"edit"|"delete"){try{if(action==="password"){const password=prompt(`为 ${member.name} 设置6位数字新密码`);if(!password)return;await req(`/users/${member.id}`,{method:"PATCH",headers:headers(true),body:JSON.stringify({password})})}else if(action==="disable"){if(!confirm(`确认停用 ${member.name}？停用后该成员会立即无法登录。`))return;await req(`/users/${member.id}`,{method:"PATCH",headers:headers(true),body:JSON.stringify({role:"disabled"})})}else if(action==="enable"){await req(`/users/${member.id}`,{method:"PATCH",headers:headers(true),body:JSON.stringify({role:"consultant"})})}else if(action==="edit"){const name=prompt("成员姓名",member.name);if(!name)return;const phone=prompt("登录手机号",member.phone||"");if(!phone)return;const available=roles.map(r=>`${r.code}=${r.name}`).join("、");const role=prompt(`角色代码（${available}）`,member.role==="disabled"?"consultant":member.role);if(!role)return;await req(`/users/${member.id}`,{method:"PATCH",headers:headers(true),body:JSON.stringify({name,phone,role})})}else{if(!confirm(`确认删除成员“${member.name}”？该成员将不能再登录，历史业务记录仍会保留。`))return;await req(`/users/${member.id}`,{method:"DELETE",headers:headers()})}setUsers(await req("/users",{headers:headers()}))}catch(e){alert((e as Error).message)}}
 async function addRole(){const name=prompt("请输入新角色名称，例如：招聘助理");if(!name)return;try{await req("/roles",{method:"POST",headers:headers(true),body:JSON.stringify({name})});setRoles(await req("/roles",{headers:headers()}))}catch(e){alert((e as Error).message)}}
 async function deleteRole(role:RoleOption){if(!confirm(`确认删除角色“${role.name}”？`))return;try{await req(`/roles/${role.code}`,{method:"DELETE",headers:headers()});setRoles(await req("/roles",{headers:headers()}))}catch(e){alert((e as Error).message)}}
 async function editCandidate(c:Candidate){if(user?.role==="admin"||user?.role==="manager"){try{setUsers(await req("/users",{headers:headers()}))}catch{}}setSelected(null);setEditing(c);setModal("candidateEdit")}
 async function deleteCandidate(c:Candidate){if(user?.role!=="admin"&&user?.role!=="manager"){alert("仅管理员可删除人才");return}if(!confirm(`确认删除 ${c.name}？相关流程、跟进和附件记录也会删除。`))return;await req(`/candidates/${c.id}`,{method:"DELETE",headers:headers()});setSelected(null);await refresh()}
 function editClient(c:Client){setEditing(c);setModal("client")}
 function editJob(j:Job){setEditing(j);setModal("job")}
 async function saveProfile(e:FormEvent<HTMLFormElement>){e.preventDefault();const form=e.currentTarget;const f=new FormData(form);const body={name:f.get("name"),phone:f.get("phone"),email:f.get("email"),old_password:f.get("old_password")||null,new_password:f.get("new_password")||null};try{const updated=await req("/me",{method:"PATCH",headers:headers(true),body:JSON.stringify(body)});setUser(updated);sessionStorage.setItem("lingyao_user",JSON.stringify(updated));form.querySelectorAll<HTMLInputElement>('input[type="password"]').forEach(x=>x.value="");alert("个人资料已保存。手机号修改后，下次请使用新手机号登录。") }catch(e){alert((e as Error).message)}}
 async function uploadAvatar(file?:File){if(!file)return;const f=new FormData();f.append("file",file);try{await req("/me/avatar",{method:"POST",headers:headers(),body:f});const updated=await req("/me",{headers:headers()});setUser(updated);sessionStorage.setItem("lingyao_user",JSON.stringify(updated))}catch(e){alert((e as Error).message)}}
 async function parseResume(file?:File){if(!file)return;const f=new FormData();f.append("file",file);try{const x=await req("/resumes/parse",{method:"POST",headers:headers(),body:f});alert(`解析完成\n姓名：${x.fields.name||"未识别"}\n手机号：${x.fields.phone||"未识别"}\n邮箱：${x.fields.email||"未识别"}`)}catch(e){alert((e as Error).message)}}
 async function move(app:Application,stage:string){await req(`/pipeline/${app.id}/stage`,{method:"PATCH",headers:headers(true),body:JSON.stringify({stage})});await refresh()}
 async function search(e:FormEvent){e.preventDefault();setPeople(await req(`/candidates?q=${encodeURIComponent(query)}`,{headers:headers()}))}
 if(publicToken)return <PublicFormCustom token={publicToken}/>;
 if(!token)return <Login onSubmit={login} error={error}/>;
 if(!user)return <main className="login-page"><section className="login-card"><h2>正在加载工作台…</h2><p className="login-sub">正在验证账号信息，请稍候。</p></section></main>;
 const titles:Record<View,[string,string]>={dashboard:["工作台","团队业务概览"],candidates:["人才库","公司与个人候选人档案"],clients:["客户管理","维护客户及关键联系人"],jobs:["职位管理","管理委托职位与交付状态"],pipeline:["招聘流程","按职位推进候选人阶段"],resumeFlow:["简历流程","申请表、性格测试与面试邀请"],settings:["系统设置","团队成员、权限与安全"],profile:["个人资料","修改姓名、邮箱、头像和登录密码"]};
 return <main className="shell"><Sidebar view={view} setView={chooseView} user={user!} logout={logout}/><section className="content"><header><div><p>财富自由之路 / {titles[view][0]}</p><h1>{titles[view][0]}</h1><small className="page-sub">{titles[view][1]}</small></div><Actions view={view} setModal={x=>{setEditing(null);setModal(x)}} parseResume={parseResume} fileRef={fileRef}/></header>{view==="dashboard"&&<DashboardView data={dash}/>} {view==="candidates"&&<CandidatesView people={people} jobs={jobs} clients={clients} apps={apps} query={query} setQuery={setQuery} search={search} open={openCandidate}/>} {view==="clients"&&<ClientsView clients={clients} edit={editClient}/>} {view==="jobs"&&<JobsView jobs={jobs} clients={clients} edit={editJob}/>} {view==="pipeline"&&<PipelineView apps={apps} people={people} jobs={jobs} move={move}/>} {view==="resumeFlow"&&<ResumeFlowView flows={flows} senders={senders} templates={templates} copy={copyLink} print={printFlow} addSender={()=>setModal("sender")} addTemplate={()=>setModal("template")} editTemplate={setTemplateEditing} deleteTemplate={deleteTemplate}/>} {view==="settings"&&<SettingsView current={user!} users={users} roles={roles} update={updateMember} addRole={addRole} deleteRole={deleteRole}/>} {view==="profile"&&<ProfileView user={user!} save={saveProfile} upload={uploadAvatar}/>}</section>{selected&&<CandidateDrawer person={selected} close={()=>setSelected(null)} addNote={addNote} upload={uploadAttachment} download={downloadAttachment} edit={editCandidate} remove={deleteCandidate} setModal={setModal}/>} {templateEditing&&<TemplateEditModal template={templateEditing} close={()=>setTemplateEditing(null)} submit={updateTemplate} senders={senders}/>} {modal==="template"&&<TemplateModal close={()=>setModal(null)} submit={submitFlow} senders={senders}/>} {modal==="candidateEdit"&&editing&&<CandidateEditModal person={editing as Candidate} users={users} close={()=>{setModal(null);setEditing(null)}} submit={submitEntity}/>} {modal==="resumeUpload"&&<ResumeUploadModal close={()=>setModal(null)} submit={uploadResume} jobs={jobs}/>} {modal&&modal!=="template"&&modal!=="candidateEdit"&&modal!=="resumeUpload"&&<EntityModal kind={modal} editing={(modal==="client"||modal==="job")?editing as Client|Job:null} close={()=>{setModal(null);setEditing(null)}} submit={modal==="resumeFlow"||modal==="sender"?submitFlow:submitEntity} clients={clients} jobs={jobs} people={people} senders={senders} roles={roles}/>}</main>
}

function Login({onSubmit,error}:{onSubmit:(e:FormEvent<HTMLFormElement>)=>void,error:string}){return <main className="login-page"><section className="login-card"><div className="login-brand"><span className="brandmark">财</span><div><h1>财富自由之路</h1><p>WEALTH FREEDOM</p></div></div><h2>欢迎回来</h2><p className="login-sub">使用手机号码登录团队工作台。</p><form onSubmit={onSubmit}><label>手机号码<input name="phone" type="tel" inputMode="numeric" pattern="1[3-9][0-9]{9}" defaultValue="13800000000" required/></label><label>6位数字密码<input name="password" type="password" inputMode="numeric" pattern="[0-9]{6}" maxLength={6} autoFocus required/></label>{error&&<div className="error">{error}</div>}<button className="primary login-btn">登录系统</button></form><div className="demo-tip"><strong>请使用管理员分配的手机号和密码登录</strong></div></section><aside className="login-art"><div><span>为猎头团队而生</span><h2>人才、客户与交付进度，<br/>在一个地方清晰协作。</h2><p>从人才入库到成功回款，完整记录每一步。</p></div></aside></main>}
function Sidebar({view,setView,user,logout}:{view:View,setView:(v:View)=>void,user:User,logout:()=>void}){const nav:[View,string,string][]=[["dashboard","⌂","工作台"],["candidates","♙","人才库"],["jobs","▣","职位管理"],["clients","◇","客户管理"],["pipeline","⇢","招聘流程"],["resumeFlow","▤","简历流程"],["settings","⚙","系统设置"]];return <aside className="sidebar"><div className="brand"><span className="brandmark">财</span><div><strong>财富自由之路</strong><small>WEALTH FREEDOM</small></div></div><nav>{nav.map(([id,icon,label])=><button key={id} onClick={()=>setView(id)} className={view===id?"nav-active":""}>{icon}<span>{label}</span></button>)}</nav><div className="nav-foot"><button className={view==="profile"?"nav-active":""} onClick={()=>setView("profile")}>◎<span>个人资料</span></button><div className="profile"><Avatar user={user}/><div><strong>{user.name}</strong><small>{roleName(user.role)}</small></div><button className="logout" onClick={logout}>退出</button></div></div></aside>}
function Actions({view,setModal,parseResume,fileRef}:{view:View,setModal:(x:any)=>void,parseResume:(f?:File)=>void,fileRef:any}){return <div className="header-actions">{view==="candidates"&&<><button className="ghost" onClick={()=>setModal("job")}>＋ 新建岗位分组</button><button className="ghost" onClick={()=>setModal("resumeUpload")}>↑ 上传简历</button><button className="primary" onClick={()=>setModal("candidate")}>＋ 新增人才</button></>}{view==="clients"&&<button className="primary" onClick={()=>setModal("client")}>＋ 新增客户</button>}{view==="jobs"&&<button className="primary" onClick={()=>setModal("job")}>＋ 新增职位</button>}{view==="pipeline"&&<button className="primary" onClick={()=>setModal("application")}>＋ 加入流程</button>}{view==="resumeFlow"&&<button className="primary" onClick={()=>setModal("resumeFlow")}>＋ 发起简历流程</button>}{view==="settings"&&<button className="primary" onClick={()=>setModal("user")}>＋ 添加成员</button>}</div>}
function DashboardView({data}:{data:Dashboard|null}){return <><div className="stats"><article><span>人才总数</span><strong>{data?.candidates??"—"}</strong><em>公司共享人才库</em></article><article><span>活跃职位</span><strong>{data?.open_jobs??"—"}</strong><em>正在交付</em></article><article><span>客户数量</span><strong>{data?.clients??"—"}</strong><em>已建立合作档案</em></article><article><span>进行中流程</span><strong>{data?.active_pipeline??"—"}</strong><em>等待下一步推进</em></article></div><section className="panel"><div className="panel-title"><div><h2>招聘漏斗</h2><p>当前所有职位的候选人阶段分布</p></div></div><div className="funnel">{stages.map(s=><div key={s}><span>{s}</span><b>{data?.stages?.[s]||0}</b><i style={{width:`${Math.max(8,(data?.stages?.[s]||0)*18)}%`}}/></div>)}</div></section></>}
function CandidatesView({people,jobs,clients,apps,query,setQuery,search,open}:{people:Candidate[],jobs:Job[],clients:Client[],apps:Application[],query:string,setQuery:(x:string)=>void,search:(e:FormEvent)=>void,open:(c:Candidate)=>void}){const[group,setGroup]=useState("all");const groupedPeople=group==="all"?people:group==="ungrouped"?people.filter(p=>!apps.some(a=>a.candidate_id===p.id)):people.filter(p=>apps.some(a=>a.candidate_id===p.id&&a.job_id===Number(group)));const groupTitle=group==="all"?"全部人才":group==="ungrouped"?"未分组人才":jobs.find(j=>j.id===Number(group))?.title||"岗位分组";const stageLabel=(stage?:string)=>!stage?"投递中":stage==="面试"?"面试中":stage==="Offer"?"谈薪中":["入职","保证期","回款"].includes(stage)?"入职中":"投递中";const latestApp=(candidateId:number)=>apps.filter(a=>a.candidate_id===candidateId&&(group==="all"||group==="ungrouped"||a.job_id===Number(group))).sort((a,b)=>new Date(b.updated_at).getTime()-new Date(a.updated_at).getTime())[0];return <><form className="toolbar" onSubmit={search}><div className="search">⌕ <input value={query} onChange={e=>setQuery(e.target.value)} placeholder="搜索姓名、公司、岗位、学校或关键词"/></div><button>搜索</button></form><div className="job-groups"><button className={group==="all"?"active":""} onClick={()=>setGroup("all")}>全部人才 <b>{people.length}</b></button>{jobs.map(j=>{const count=new Set(apps.filter(a=>a.job_id===j.id).map(a=>a.candidate_id)).size;return <button className={group===String(j.id)?"active":""} onClick={()=>setGroup(String(j.id))} key={j.id}>{j.title} <b>{count}</b></button>})}<button className={group==="ungrouped"?"active":""} onClick={()=>setGroup("ungrouped")}>未分组 <b>{people.filter(p=>!apps.some(a=>a.candidate_id===p.id)).length}</b></button></div><section className="panel table-panel talent-table-wrap"><div className="panel-title"><div><h2>{groupTitle}</h2><p>共 {groupedPeople.length} 位候选人，点击任意一行查看或编辑完整档案</p></div></div><div className="talent-scroll"><div className="table-head talent-grid"><span>序号</span><span>姓名</span><span>岗位</span><span>公司</span><span>性别</span><span>所在城市</span><span>毕业学校</span><span>毕业时间</span><span>联系方式</span><span>所属顾问</span><span>目前状态</span></div>{groupedPeople.map((c,index)=>{const app=latestApp(c.id);const job=app?jobs.find(j=>j.id===app.job_id):undefined;const client=job?clients.find(x=>x.id===job.client_id):undefined;return <button className="table-row talent-grid" key={c.id} onClick={()=>open(c)}><span>{index+1}</span><strong>{c.name}</strong><span>{job?.title||c.current_title||"未分组"}</span><span>{client?.name||c.current_company||"—"}</span><span>{c.gender||"—"}</span><span>{c.city||"—"}</span><span>{c.school||"—"}</span><span>{c.graduation_time||"—"}</span><span className="talent-contact">{c.phone||"—"}<small>{c.email||""}</small></span><span>{c.owner_name||`顾问 #${c.owner_id}`}</span><span className={`status-pill status-${stageLabel(app?.stage)}`}>{stageLabel(app?.stage)}</span></button>})}{!groupedPeople.length&&<div className="empty">该岗位分组暂无候选人</div>}</div></section></>}
function ClientsView({clients,edit}:{clients:Client[],edit:(c:Client)=>void}){return <section className="card-grid">{clients.map(c=><article className="entity-card" key={c.id}><div className="entity-icon">{c.name[0]}</div><div><h3>{c.name}</h3><p>{c.industry||"行业待完善"}</p></div><button className="mini-edit" onClick={()=>edit(c)}>编辑</button><dl><div><dt>联系人</dt><dd>{c.contact_name||"—"}</dd></div><div><dt>联系电话</dt><dd>{c.contact_phone||"—"}</dd></div></dl></article>)}{!clients.length&&<div className="empty panel">尚未建立客户档案</div>}</section>}
function JobsView({jobs,clients,edit}:{jobs:Job[],clients:Client[],edit:(j:Job)=>void}){return <section className="panel table-panel"><div className="table-head job-grid"><span>职位</span><span>客户</span><span>城市 / 年薪</span><span>状态 / 操作</span></div>{jobs.map(j=><div className="table-row job-grid" key={j.id}><div><strong>{j.title}</strong><small>负责人 #{j.owner_id}</small></div><div>{clients.find(c=>c.id===j.client_id)?.name||`客户 #${j.client_id}`}</div><div><strong>{j.city||"—"}</strong><small>{j.salary||"薪资面议"}</small></div><div><span className={`badge ${j.status}`}>{j.status==="open"?"招聘中":"已关闭"}</span><button className="mini-edit" onClick={()=>edit(j)}>编辑</button></div></div>)}</section>}
function PipelineView({apps,people,jobs,move}:{apps:Application[],people:Candidate[],jobs:Job[],move:(a:Application,s:string)=>void}){return <div className="kanban">{stages.map(stage=><section key={stage} className="kanban-col"><header><span>{stage}</span><b>{apps.filter(a=>a.stage===stage).length}</b></header>{apps.filter(a=>a.stage===stage).map(a=><article key={a.id}><strong>{people.find(p=>p.id===a.candidate_id)?.name||`人才 #${a.candidate_id}`}</strong><p>{jobs.find(j=>j.id===a.job_id)?.title||`职位 #${a.job_id}`}</p><select value={a.stage} onChange={e=>move(a,e.target.value)}>{stages.map(s=><option key={s}>{s}</option>)}</select></article>)}</section>)}</div>}
function SettingsView({current,users,roles,update,addRole,deleteRole}:{current:User,users:User[],roles:RoleOption[],update:(u:User,a:"password"|"disable"|"enable"|"edit"|"delete")=>void,addRole:()=>void,deleteRole:(r:RoleOption)=>void}){if(current.role!=="admin"&&current.role!=="manager")return <section className="panel empty">仅管理员可查看团队设置。</section>;const label=(code:string)=>code==="disabled"?"已停用":roles.find(r=>r.code===code)?.name||roleName(code);return <><section className="panel table-panel"><div className="panel-title"><div><h2>角色管理</h2><p>可新建团队岗位角色；内置角色不可删除</p></div><button className="primary" onClick={addRole}>＋ 新增角色</button></div><div className="member-actions">{roles.map(r=><span className="badge" key={r.code}>{r.name}{!r.builtin&&<button className="danger" onClick={()=>deleteRole(r)}>删除</button>}</span>)}</div></section><section className="panel table-panel"><div className="panel-title"><div><h2>团队成员</h2><p>可修改资料、角色及登录状态；删除后历史业务记录仍保留</p></div></div><div className="table-head user-grid"><span>成员</span><span>登录手机号</span><span>角色 / 操作</span></div>{users.map(u=><div className="table-row user-grid" key={u.id}><strong>{u.name}</strong><span>{u.phone||"待设置"}</span><div className="member-actions"><span className="badge">{label(u.role)}</span><button onClick={()=>update(u,"edit")}>修改</button><button onClick={()=>update(u,"password")}>重置密码</button>{u.id!==current.id&&u.role!=="disabled"&&<button onClick={()=>update(u,"disable")}>停用</button>}{u.id!==current.id&&u.role==="disabled"&&<button onClick={()=>update(u,"enable")}>启用</button>}{u.id!==current.id&&<button className="danger" onClick={()=>update(u,"delete")}>删除</button>}</div></div>)}</section></>}
function ResumeFlowView({flows,senders,templates,copy,print,addSender,addTemplate,editTemplate,deleteTemplate}:{flows:ResumeFlow[],senders:Sender[],templates:FormTemplate[],copy:(x:ResumeFlow)=>void,print:(x:ResumeFlow)=>void,addSender:()=>void,addTemplate:()=>void,editTemplate:(t:FormTemplate)=>void,deleteTemplate:(t:FormTemplate)=>void}){return <><section className="flow-summary"><article><b>{flows.filter(x=>x.status==="待填写").length}</b><span>待候选人填写</span></article><article><b>{flows.filter(x=>x.status==="已填写").length}</b><span>已回收表单</span></article><article><b>{templates.length}</b><span>申请表 / 测试模板</span></article><div className="flow-top-actions"><button className="ghost" onClick={addTemplate}>＋ 新建或上传模板</button><button className="ghost" onClick={addSender}>＋ 公司主体</button></div></section><section className="template-strip">{templates.map(t=><article key={t.id}><b>{t.name}</b><span>{flowLabel(t.template_type)} · {t.fields.length} 个问题</span>{t.source_file_name&&<small>上传自 {t.source_file_name}</small>}<div className="template-actions"><button onClick={()=>editTemplate(t)}>修改</button><button className="danger" onClick={()=>deleteTemplate(t)}>删除</button></div></article>)}</section><section className="panel table-panel"><div className="table-head flow-grid"><span>候选人与内容</span><span>公司主体 / 职位</span><span>发送与填写状态</span><span>操作</span></div>{flows.map(x=><div className="table-row flow-grid" key={x.id}><div><strong>{x.candidate_name} · {flowLabel(x.flow_type)}</strong><small>{new Date(x.created_at).toLocaleString("zh-CN")}</small></div><div><strong>{x.sender_name}</strong><small>{x.job_title||"未关联职位"}</small></div><div><span className="badge">{x.status}</span><small>{x.sms_status}</small></div><div className="flow-actions"><button onClick={()=>copy(x)}>复制短信链接</button>{x.status==="已填写"&&<button onClick={()=>print(x)}>打印 / PDF</button>}</div></div>)}{!flows.length&&<div className="empty">尚未发起申请表、测试或面试邀请</div>}</section></>}
function PublicForm({token}:{token:string}){const[data,setData]=useState<any>(null);const[done,setDone]=useState(false);const[err,setErr]=useState("");useEffect(()=>{fetch(`${apiBase()}/public/resume-flow/${token}`).then(async r=>{if(!r.ok)throw new Error((await r.json()).detail||"链接无效");return r.json()}).then(setData).catch(e=>setErr(e.message))},[token]);async function submit(e:FormEvent<HTMLFormElement>){e.preventDefault();const answers=Object.fromEntries(new FormData(e.currentTarget));const r=await fetch(`${apiBase()}/public/resume-flow/${token}`,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({answers})});if(r.ok)setDone(true);else setErr((await r.json()).detail||"提交失败")}if(err)return <main className="public-page"><section className="public-card"><h2>无法打开</h2><p>{err}</p></section></main>;if(!data)return <main className="public-page"><section className="public-card">正在加载…</section></main>;if(done)return <main className="public-page"><section className="public-card public-done"><div>✓</div><h2>提交成功</h2><p>感谢填写，招聘顾问将与您联系。</p></section></main>;if(data.flow_type==="interview")return <main className="public-page"><section className="public-card"><div className="public-brand">{data.sender_name}</div><h1>{data.title}</h1><p className="public-intro">候选人：{data.candidate_name}<br/>应聘职位：{data.job_title||"待确认"}</p>{data.message&&<div className="notice">{data.message}</div>}<h3>面试要求</h3><p className="requirements">{data.interview_requirements||"请按约定时间参加面试，并保持手机畅通。"}</p></section></main>;const personality=data.flow_type==="personality";return <main className="public-page"><form className="public-card" onSubmit={submit}><div className="public-brand">{data.sender_name}</div><h1>{data.form_header||data.title}</h1><p className="public-intro">候选人：{data.candidate_name}　应聘职位：{data.job_title||"待确认"}</p>{personality?<><PublicSelect name="我更喜欢的工作方式" options={["独立完成","团队协作","两者均可"]}/><PublicSelect name="面对压力时" options={["立即行动解决","先分析再行动","寻求团队支持"]}/><PublicSelect name="决策风格" options={["依据数据","依据经验","综合判断"]}/><PublicSelect name="沟通偏好" options={["直接明确","温和周全","视对象调整"]}/><label>请描述您的优势<textarea name="个人优势" required/></label></>:<><label>姓名<input name="姓名" defaultValue={data.candidate_name} required/></label><label>手机号码<input name="手机号码" type="tel" required/></label><label>电子邮箱<input name="电子邮箱" type="email"/></label><label>身份证号<input name="身份证号"/></label><label>现居住城市<input name="现居住城市" required/></label><label>最高学历<input name="最高学历" required/></label><label>当前公司及职位<input name="当前公司及职位" required/></label><label>目前年薪<input name="目前年薪"/></label><label>期望年薪<input name="期望年薪"/></label><label>可到岗时间<input name="可到岗时间"/></label><label>离职原因及求职动机<textarea name="离职原因及求职动机" required/></label><label>主要工作经历<textarea name="主要工作经历" required/></label></>}<label className="consent"><input type="checkbox" required/>本人确认以上信息真实，并同意用于本次招聘评估。</label><button className="primary public-submit">确认提交</button></form></main>}
function PublicSelect({name,options}:{name:string,options:string[]}){return <label>{name}<select name={name} required><option value="">请选择</option>{options.map(x=><option key={x}>{x}</option>)}</select></label>}
function TemplateEditModal({template,close,submit,senders}:{template:FormTemplate,close:()=>void,submit:(e:FormEvent<HTMLFormElement>)=>void,senders:Sender[]}){const questions=template.fields.map(f=>`${f.label}|${f.type}${f.options?.length?`|${f.options.join(",")}`:""}`).join("\n");return <div className="modal-bg" onMouseDown={e=>{if(e.target===e.currentTarget)close()}}><form className="modal template-modal" onSubmit={submit}><div className="modal-title"><div><h2>修改表单模板</h2><p>可修改名称、公司主体和在线问题</p></div><button type="button" onClick={close}>×</button></div><div className="form-grid"><Field name="name" label="模板名称" required value={template.name}/><Select name="template_type" label="模板类型" value={template.template_type} options={[["application","求职申请表"],["personality","性格测试"]]}/><Select name="sender_id" label="适用公司主体" value={template.sender_id||""} options={[["","全部公司"],...senders.map(s=>[s.id,s.display_name])]}/><Field name="description" label="模板说明" value={template.description}/><label className="wide-field">在线编辑问题<textarea name="questions" rows={12} defaultValue={questions}/><small>每行一个问题；格式：问题|text，长文本使用 textarea，选择题使用 select|选项1,选项2。</small></label></div><div className="modal-actions"><button type="button" className="ghost" onClick={close}>取消</button><button className="primary">保存修改</button></div></form></div>}
function TemplateModal({close,submit,senders}:{close:()=>void,submit:(e:FormEvent<HTMLFormElement>)=>void,senders:Sender[]}){return <div className="modal-bg" onMouseDown={e=>{if(e.target===e.currentTarget)close()}}><form className="modal template-modal" onSubmit={submit}><div className="modal-title"><div><h2>新建或上传表单模板</h2><p>在线编辑问题，或上传 DOCX、PDF、TXT 自动识别</p></div><button type="button" onClick={close}>×</button></div><div className="form-grid"><Field name="name" label="模板名称" required/><Select name="template_type" label="模板类型" options={[["application","求职申请表"],["personality","性格测试"]]}/><Select name="sender_id" label="适用公司主体" options={[["","全部公司"],...senders.map(s=>[s.id,s.display_name])]}/><Field name="description" label="模板说明"/><label className="wide-field">上传现有模板（选填）<input name="file" type="file" accept=".docx,.pdf,.txt"/><small>上传文件后，系统会把其中每一行文字转换成一个可填写问题。</small></label><label className="wide-field">在线编辑问题（未上传文件时使用）<textarea name="questions" rows={10} placeholder={'姓名|text\n手机号码|text\n个人优势|textarea\n工作偏好|select|独立完成,团队协作,均可'}/><small>每行一个问题；支持 text、textarea、select。选择题在第三段填写选项并用逗号分隔。</small></label></div><div className="modal-actions"><button type="button" className="ghost" onClick={close}>取消</button><button className="primary">保存模板</button></div></form></div>}
function CandidateEditModal({person,users,close,submit}:{person:Candidate,users:User[],close:()=>void,submit:(e:FormEvent<HTMLFormElement>)=>void}){const ownerOptions=users.length?users.filter(u=>u.role!=="disabled").map(u=>[u.id,`${u.name}（${roleName(u.role)}）`]):[[person.owner_id,`顾问 #${person.owner_id}`]];return <div className="modal-bg" onMouseDown={e=>{if(e.target===e.currentTarget)close()}}><form className="modal candidate-edit-modal" onSubmit={submit}><div className="modal-title"><div><h2>编辑人才档案</h2><p>所在地、经验、联系方式和归属均可修改</p></div><button type="button" onClick={close}>×</button></div><div className="form-grid"><Field name="name" label="姓名" required value={person.name}/><Select name="gender" label="性别" options={[["","未填写"],["男","男"],["女","女"],["其他","其他"]]} value={person.gender||""}/><Field name="city" label="所在地" value={person.city}/><Field name="phone" label="手机号码" type="tel" value={person.phone}/><Field name="email" label="电子邮箱" type="email" value={person.email}/><Field name="years" label="工作经验（年）" type="number" value={person.years?.toString()}/><Field name="expected_salary" label="期望年薪" value={person.expected_salary}/><Field name="current_company" label="当前公司" value={person.current_company}/><Field name="current_title" label="当前职位" value={person.current_title}/><Field name="school" label="毕业院校" value={person.school}/><Field name="degree" label="最高学历" value={person.degree}/><Field name="graduation_time" label="毕业时间" value={person.graduation_time}/><Select name="owner_id" label="归属顾问" options={ownerOptions} value={person.owner_id}/><Select name="visibility" label="人才库范围" options={[["company","公司人才库"],["private","个人人才库"]]} value={(person as any).visibility||"company"}/><label className="wide-field">人才简介 / 备注<textarea name="summary" defaultValue={person.summary||""}/></label></div><div className="modal-actions"><button type="button" className="ghost" onClick={close}>取消</button><button className="primary">保存修改</button></div></form></div>}
function PublicFormCustom({token}:{token:string}){const[data,setData]=useState<any>(null);const[done,setDone]=useState(false);const[err,setErr]=useState("");useEffect(()=>{fetch(`${apiBase()}/public/resume-flow/${token}`).then(async r=>{if(!r.ok)throw new Error((await r.json()).detail||"链接无效");return r.json()}).then(setData).catch(e=>setErr(e.message))},[token]);async function submit(e:FormEvent<HTMLFormElement>){e.preventDefault();const answers=Object.fromEntries(new FormData(e.currentTarget));const r=await fetch(`${apiBase()}/public/resume-flow/${token}`,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({answers})});if(r.ok)setDone(true);else setErr((await r.json()).detail||"提交失败")}if(err)return <main className="public-page"><section className="public-card"><h2>无法打开</h2><p>{err}</p></section></main>;if(!data)return <main className="public-page"><section className="public-card">正在加载…</section></main>;if(done)return <main className="public-page"><section className="public-card public-done"><div>✓</div><h2>提交成功</h2><p>感谢填写，招聘顾问将与您联系。</p></section></main>;if(data.flow_type==="interview")return <main className="public-page"><section className="public-card"><div className="public-brand">{data.sender_name}</div><h1>{data.title}</h1><p className="public-intro">候选人：{data.candidate_name}<br/>应聘职位：{data.job_title||"待确认"}</p>{data.message&&<div className="notice">{data.message}</div>}<h3>面试要求</h3><p className="requirements">{data.interview_requirements||"请按约定时间参加面试，并保持手机畅通。"}</p></section></main>;return <main className="public-page"><form className="public-card" onSubmit={submit}><div className="public-brand">{data.sender_name}</div><h1>{data.form_header||data.title}</h1><p className="public-intro">候选人：{data.candidate_name}　应聘职位：{data.job_title||"待确认"}</p>{(data.fields||[]).map((f:any,i:number)=><DynamicPublicField field={f} key={`${f.label}-${i}`}/>) }<label className="consent"><input type="checkbox" required/>本人确认以上信息真实，并同意用于本次招聘评估。</label><button className="primary public-submit">确认提交</button></form></main>}
function ResumeUploadModal({close,submit,jobs}:{close:()=>void,submit:(e:FormEvent<HTMLFormElement>)=>void,jobs:Job[]}){return <div className="modal-bg" onMouseDown={e=>{if(e.target===e.currentTarget)close()}}><form className="modal" onSubmit={submit}><div className="modal-title"><div><h2>上传简历</h2><p>无需提前选择候选人。系统会自动解析简历、创建人才档案并保存到持久化存储。</p></div><button type="button" onClick={close}>×</button></div><div className="form-grid"><Select name="job_id" label="选择岗位分组" options={jobs.filter(j=>j.status==="open").map(j=>[j.id,j.title])}/><label>简历文件<input name="file" type="file" accept=".pdf,.docx" required/></label></div><div className="modal-actions"><button type="button" className="ghost" onClick={close}>取消</button><button className="primary">上传并自动建档</button></div></form></div>}
function DynamicPublicField({field}:{field:any}){if(field.type==="select")return <PublicSelect name={field.label} options={field.options||[]}/>;return <label>{field.label}{field.type==="textarea"?<textarea name={field.label} required={field.required!==false}/>:<input name={field.label} required={field.required!==false}/>}</label>}
function flowLabel(type:string){return {application:"求职申请表",personality:"性格测试",interview:"面试邀请"}[type]||type}
function CandidateDrawer({person,close,addNote,upload,download,edit,remove,setModal}:{person:Candidate,close:()=>void,addNote:(e:FormEvent<HTMLFormElement>)=>void,upload:(f?:File)=>void,download:(a:Attachment)=>void,edit:(c:Candidate)=>void,remove:(c:Candidate)=>void,setModal:(x:any)=>void}){return <aside className="drawer live-drawer"><div className="drawer-top"><button onClick={close}>×</button><span>人才完整档案</span></div><div className="identity"><span>{person.name[0]}</span><div><h2>{person.name}</h2><p>{person.current_title||"职位待完善"}</p><small>{person.current_company||"公司待完善"} · {person.city||"城市待完善"}</small></div></div><div className="contact-detail"><span>手机：{person.phone||"未填写"}</span><span>邮箱：{person.email||"未填写"}</span></div><div className="record-actions"><button onClick={()=>edit(person)}>编辑档案</button><button className="danger" onClick={()=>remove(person)}>删除</button></div><div className="contact"><button onClick={()=>setModal("application")}>＋ 加入职位</button><label className="upload-btn">上传附件<input hidden type="file" onChange={e=>upload(e.target.files?.[0])}/></label></div><section className="info"><h3>职业信息</h3><dl><div><dt>工作年限</dt><dd>{person.years?`${person.years} 年`:"—"}</dd></div><div><dt>学历 / 学校</dt><dd>{person.degree||"—"} · {person.school||"—"}</dd></div><div><dt>期望薪资</dt><dd>{person.expected_salary||"—"}</dd></div><div><dt>人才归属</dt><dd>顾问 #{person.owner_id}</dd></div></dl>{person.summary&&<p className="summary">{person.summary}</p>}</section><section className="drawer-section"><h3>跟进记录</h3><form className="note-form" onSubmit={addNote}><textarea name="content" placeholder="记录沟通结果、意向和下一步…" required/><button className="primary">保存跟进</button></form>{person.notes?.map(n=><article className="note" key={n.id}><p>{n.content}</p><small>{new Date(n.created_at).toLocaleString("zh-CN")}</small></article>)}</section><section className="drawer-section"><h3>附件 ({person.attachments?.length||0})</h3>{person.attachments?.map(a=><button className="attachment" key={a.id} onClick={()=>download(a)}>▧ {a.name}<small>{Math.ceil(a.size/1024)} KB</small></button>)}</section></aside>}
function EntityModal({kind,editing,close,submit,clients,jobs,people,senders=[],roles=[]}:{kind:string,editing:Client|Job|null,close:()=>void,submit:(e:FormEvent<HTMLFormElement>)=>void,clients:Client[],jobs:Job[],people:Candidate[],senders?:Sender[],roles?:RoleOption[]}){const isEdit=!!editing;const title=isEdit?(kind==="job"?"编辑职位":"编辑客户"):({candidate:"新增候选人",client:"新增客户",job:"新增职位",user:"添加团队成员",application:"候选人加入职位",resumeFlow:"发起简历流程",sender:"新增公司发送主体"}[kind]||"新增");const client=kind==="client"?editing as Client|null:null;const job=kind==="job"?editing as Job|null:null;return <div className="modal-bg" onMouseDown={e=>{if(e.target===e.currentTarget)close()}}><form className="modal" onSubmit={submit}><div className="modal-title"><div><h2>{title}</h2>{isEdit&&<p>修改后将立即同步到团队工作台</p>}</div><button type="button" onClick={close}>×</button></div><div className="form-grid">{kind==="candidate"&&<><Field name="name" label="姓名" required/><Select name="gender" label="性别" options={[["","未填写"],["男","男"],["女","女"],["其他","其他"]]}/><Field name="phone" label="手机号"/><Field name="email" label="邮箱" type="email"/><Field name="city" label="城市"/><Field name="current_company" label="当前公司"/><Field name="current_title" label="当前职位"/><Field name="school" label="毕业院校"/><Field name="degree" label="最高学历"/><Field name="graduation_time" label="毕业时间"/><Field name="years" label="工作年限" type="number"/><Field name="expected_salary" label="期望薪资"/></>}{kind==="client"&&<><Field name="name" label="客户名称" required value={client?.name}/><Field name="industry" label="所属行业" value={client?.industry}/><Field name="contact_name" label="联系人" value={client?.contact_name}/><Field name="contact_phone" label="联系电话" value={client?.contact_phone}/></>}{kind==="job"&&<><Field name="title" label="职位名称" required value={job?.title}/><Select name="client_id" label="所属客户" options={clients.map(c=>[c.id,c.name])} value={job?.client_id}/><Field name="city" label="工作城市" value={job?.city}/><Field name="salary" label="年薪范围" value={job?.salary}/><Select name="status" label="职位状态" options={[["open","招聘中"],["closed","已关闭"]]} value={job?.status||"open"}/></>}{kind==="user"&&<><Field name="name" label="姓名" required/><Field name="phone" label="登录手机号" type="tel" required/><Field name="email" label="联系邮箱（选填）" type="email"/><Field name="password" label="初始6位数字密码" type="password" required/><Select name="role" label="角色" options={(roles.length?roles:[{code:"consultant",name:"顾问",builtin:true},{code:"manager",name:"经理",builtin:true},{code:"admin",name:"管理员",builtin:true}]).map(r=>[r.code,r.name])}/></>}{kind==="application"&&<><Select name="candidate_id" label="候选人" options={people.map(p=>[p.id,p.name])}/><Select name="job_id" label="职位" options={jobs.filter(j=>j.status==="open").map(j=>[j.id,j.title])}/><Select name="stage" label="初始阶段" options={stages.map(s=>[s,s])}/></>}{kind==="resumeFlow"&&<><Select name="flow_type" label="发送内容" options={[["application","求职申请表"],["personality","性格测试"],["interview","面试邀请"]]}/><Select name="candidate_id" label="候选人" options={people.map(p=>[p.id,p.name])}/><Select name="job_id" label="应聘职位" options={[["","不关联职位"],...jobs.filter(j=>j.status==="open").map(j=>[j.id,j.title])]}/><Select name="sender_id" label="发送公司主体" options={[["","灵曜猎聘"],...senders.filter(s=>s.enabled).map(s=>[s.id,s.display_name])]}/><Field name="recipient_phone" label="接收短信手机号" type="tel" required/><Field name="title" label="标题（选填）"/><label className="wide-field">补充说明<textarea name="message" placeholder="面试时间、地点、联系人或其他说明"/></label></>}{kind==="sender"&&<><Select name="client_id" label="关联客户" options={[["","不关联客户"],...clients.map(c=>[c.id,c.name])]}/><Field name="display_name" label="发送公司主体" required/><Field name="form_header" label="申请表表头" required/><Field name="sms_signature" label="短信签名"/><label className="wide-field">默认面试要求<textarea name="interview_requirements" placeholder="例如：请提前10分钟到达并携带简历"/></label></>}</div><div className="modal-actions"><button type="button" className="ghost" onClick={close}>取消</button><button className="primary">{isEdit?"保存修改":kind==="resumeFlow"?"生成并发送":"保存"}</button></div></form></div>}
function ProfileView({user,save,upload}:{user:User,save:(e:FormEvent<HTMLFormElement>)=>void,upload:(f?:File)=>void}){return <section className="profile-page"><article className="profile-avatar-card"><Avatar user={user} large/><h2>{user.name}</h2><p>{roleName(user.role)}</p><label className="primary avatar-upload">更换头像<input hidden type="file" accept="image/jpeg,image/png,image/webp" onChange={e=>upload(e.target.files?.[0])}/></label><small>支持 JPG、PNG、WebP，最大 3MB</small></article><form className="profile-form panel" onSubmit={save}><div className="panel-title"><div><h2>账号信息</h2><p>手机号用于登录，修改后下次需使用新手机号</p></div></div><div className="profile-fields"><Field name="name" label="显示姓名" required value={user.name}/><Field name="phone" label="登录手机号" type="tel" required value={user.phone}/><Field name="email" label="联系邮箱" type="email" required value={user.email}/><div className="profile-divider"><strong>修改密码</strong><span>不修改密码时请留空</span></div><Field name="old_password" label="当前6位密码" type="password"/><Field name="new_password" label="新6位数字密码" type="password"/></div><div className="profile-save"><button className="primary">保存修改</button></div></form></section>}
function Avatar({user,large=false}:{user:User,large?:boolean}){return user.avatar_url?<img className={large?"avatar-img large":"avatar-img"} src={`${apiBase().replace(/\/api$/,"")}${user.avatar_url}`} alt={`${user.name}的头像`}/>:<span className={large?"avatar-fallback large":"avatar-fallback"}>{user.name[0]}</span>}
function Field({name,label,type="text",required=false,value}:{name:string,label:string,type?:string,required?:boolean,value?:string}){return <label>{label}<input name={name} type={type} required={required} defaultValue={value}/></label>}
function Select({name,label,options,value}:{name:string,label:string,options:(string|number)[][],value?:string|number}){return <label>{label}<select name={name} required defaultValue={value}>{options.map(([v,t])=><option value={v} key={v}>{t}</option>)}</select></label>}
function roleName(role:string){return {admin:"管理员",manager:"经理",consultant:"顾问",disabled:"已停用"}[role]||role}
